/**
 * Dynamic Publications Loader
 * Loads publications from JSON file generated by fetch_publications.py
 */

const PUBLICATIONS_DATA_URL = 'assets/data/publications.json';

/**
 * Format author names for display
 */
function formatAuthors(authors) {
    if (!authors) return 'Unknown Authors';

    // If authors is already a string, return it
    if (typeof authors === 'string') {
        // Clean up author formatting
        return authors.replace(/\sand\s/g, ', ');
    }

    // If it's an array, join with commas
    if (Array.isArray(authors)) {
        return authors.join(', ');
    }

    return 'Unknown Authors';
}

/**
 * Create HTML for a single publication
 */
function createPublicationHTML(pub) {
    const authors = formatAuthors(pub.authors);
    const year = pub.year ? `${pub.year}` : '';

    // Format venue intelligently
    let venueText = '';
    if (pub.venue && pub.venue !== 'Unknown Venue') {
        venueText = pub.venue;
        if (year) venueText += `, ${year}`;
    } else if (year) {
        venueText = year;
    }

    let html = `
        <div class="publication-item">
            <strong>${pub.title}</strong><br/>
            <span class="authors">${authors}</span><br/>
    `;

    // Add venue line only if there's something to show
    if (venueText) {
        html += `<span class="venue">${venueText}</span><br/>`;
    }

    // Add links if available
    if (pub.url) {
        html += `<a href="${pub.url}" target="_blank">View Publication</a>`;
    } else if (pub.eprint_url) {
        html += `<a href="${pub.eprint_url}" target="_blank">View Publication</a>`;
    }

    html += `</div>`;

    return html;
}

/**
 * Render publications section
 */
function renderPublications(data) {
    const publicationsSection = document.getElementById('publications');

    if (!publicationsSection) {
        console.error('Publications section not found');
        return;
    }

    const categories = data.categories;

    let html = '<h2>Publications</h2>';

    // Journal Papers
    if (categories.journals && categories.journals.length > 0) {
        html += '<h3 style="margin-top: 20px;">Journal Papers</h3>';
        categories.journals.forEach(pub => {
            html += createPublicationHTML(pub);
        });
    }

    // Conference Papers
    if (categories.conferences && categories.conferences.length > 0) {
        html += '<h3 style="margin-top: 20px;">Conference Papers</h3>';
        categories.conferences.forEach(pub => {
            html += createPublicationHTML(pub);
        });
    }

    // Patents
    if (categories.patents && categories.patents.length > 0) {
        html += '<h3 style="margin-top: 20px;">Patents</h3>';
        categories.patents.forEach(pub => {
            html += createPublicationHTML(pub);
        });
    }

    // Thesis
    if (categories.thesis && categories.thesis.length > 0) {
        html += '<h3 style="margin-top: 20px;">Thesis</h3>';
        categories.thesis.forEach(pub => {
            html += createPublicationHTML(pub);
        });
    }

    // Other Publications
    if (categories.other && categories.other.length > 0) {
        html += '<h3 style="margin-top: 20px;">Other Publications</h3>';
        categories.other.forEach(pub => {
            html += createPublicationHTML(pub);
        });
    }

    // Add footer with update info
    const lastUpdated = data.last_updated ? new Date(data.last_updated).toLocaleDateString() : 'Unknown';
    html += `
        <div style="margin-top: 20px; font-size: 0.9em; color: #666;">
            <em>Publications auto-loaded from Google Scholar. Last updated: ${lastUpdated}</em>
        </div>
    `;

    publicationsSection.innerHTML = html;
}

/**
 * Show loading state
 */
function showLoading() {
    const publicationsSection = document.getElementById('publications');
    if (publicationsSection) {
        publicationsSection.innerHTML = `
            <h2>Publications</h2>
            <p>Loading publications...</p>
        `;
    }
}

/**
 * Show error state with fallback
 */
function showError() {
    const publicationsSection = document.getElementById('publications');
    if (publicationsSection) {
        publicationsSection.innerHTML = `
            <h2>Publications</h2>
            <p style="color: #d9534f;">Failed to load publications data.</p>
            <p>Please visit my <a href="https://scholar.google.com/citations?user=tOsSkM4AAAAJ" target="_blank">Google Scholar profile</a> to view my publications.</p>
        `;
    }
}

/**
 * Load publications from JSON file
 */
async function loadPublications() {
    showLoading();

    try {
        const response = await fetch(PUBLICATIONS_DATA_URL);

        if (!response.ok) {
            throw new Error(`Failed to load publications: ${response.status}`);
        }

        const data = await response.json();
        renderPublications(data);
    } catch (error) {
        console.error('Error loading publications:', error);
        showError();
    }
}

/**
 * Initialize on page load
 */
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', loadPublications);
} else {
    loadPublications();
}
